properties.--item-width:
calc(
        (
            min(
                100vw - var(--container-gutter) * 2,
                var(--container-max-width-minus-gutters)
              ) - 56px
          ) / var(--section-products-per-row) -
          (
            var(--grid-gap) / var(--section-products-per-row) *
              (var(--section-products-per-row) - 1)
          )
      )
